import { badRequest } from './errors.js';

export const MAX_NAME_LENGTH = 255;

/**
 * Cleans a user-supplied file or folder name. Names are only ever DISPLAY
 * names (storage keys are generated by the server), but we still remove path
 * separators and control characters so a name can never look like a path.
 */
export function sanitizeName(raw: string): string {
  const cleaned = raw
    .normalize('NFC')
    .replace(/[\u0000-\u001f\u007f]/g, '') // control characters
    .replace(/[/\\]/g, '_') // path separators
    .replace(/\s+/g, ' ')
    .trim();

  if (cleaned === '' || cleaned === '.' || cleaned === '..') {
    throw badRequest('Name cannot be empty');
  }
  if (cleaned.length > MAX_NAME_LENGTH) {
    throw badRequest(`Name must be at most ${MAX_NAME_LENGTH} characters`);
  }
  return cleaned;
}

/** "report.final.pdf" -> ["report.final", ".pdf"]; "README" -> ["README", ""] */
export function splitExtension(name: string): [string, string] {
  const dot = name.lastIndexOf('.');
  if (dot <= 0) return [name, ''];
  return [name.slice(0, dot), name.slice(dot)];
}

/**
 * Given the names already used in a folder, returns `name` if it is free,
 * otherwise "name (1).ext", "name (2).ext", ... (case-insensitive, like Windows).
 */
export function pickUniqueName(name: string, takenNames: Iterable<string>, isFolder = false): string {
  const taken = new Set(Array.from(takenNames, (n) => n.toLowerCase()));
  if (!taken.has(name.toLowerCase())) return name;

  const [base, ext] = isFolder ? [name, ''] : splitExtension(name);
  for (let i = 1; ; i++) {
    const candidate = `${base} (${i})${ext}`;
    if (!taken.has(candidate.toLowerCase())) return candidate;
  }
}
